    def parse_version(version):
        components = version.split('.')
        parsed = []
        for comp in components:
            if not comp.isdigit():
                raise ValueError(f"Non-digit character in version: {version}")
            parsed.append(int(comp))
        return parsed

    left_parsed = parse_version(left)
    right_parsed = parse_version(right)

    max_length = max(len(left_parsed), len(right_parsed))

    for i in range(max_length):
        left_comp = left_parsed[i] if i < len(left_parsed) else 0
        right_comp = right_parsed[i] if i < len(right_parsed) else 0

        if left_comp < right_comp:
            return -1
        elif left_comp > right_comp:
            return 1

    return 0

