def invert_multimap(mapping):
    """
    Invert a multimap from owners -> list of tags to tags -> list of owners.

    Args:
        mapping (dict[str, list[str]]): Mapping of owners to their tags.

    Returns:
        dict[str, list[str]]: Mapping of each tag to a list of owners that have that tag.
                              The order of owners follows the order they appear in the
                              input mapping. Duplicate owners for the same tag are omitted.
    """
    result = {}
    # Keep a set per tag to avoid duplicate owners
    seen = {}

    for owner, tags in mapping.items():
        for tag in tags:
            if tag not in result:
                result[tag] = []
                seen[tag] = set()
            if owner not in seen[tag]:
                result[tag].append(owner)
                seen[tag].add(owner)

    return result

