def deep_merge(left, right):
    result = dict(left)
    for key, value in right.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result

def deep_merge(left, right):
    """
    Recursively merge two dictionaries.

    - If a key exists in both dictionaries and both values are dicts,
      merge those dicts recursively.
    - Otherwise, the value from ``right`` replaces the one from ``left``.
    - Lists and other non-dict values are replaced, not merged.
    - Neither ``left`` nor ``right`` is mutated; a new dictionary is returned.
    """
    # Start with a shallow copy of left to avoid mutating it
    result = {}
    for key, value in left.items():
        # For mutable values like dicts we also need a copy to avoid side‑effects
        if isinstance(value, dict):
            result[key] = deep_merge(value, {})
        else:
            result[key] = value

    for key, right_value in right.items():
        left_value = result.get(key, None)

        if isinstance(left_value, dict) and isinstance(right_value, dict):
            # Both are dicts -> merge recursively
            result[key] = deep_merge(left_value, right_value)
        else:
            # Otherwise replace with right's value (lists, scalars, etc.)
            # Ensure we don't keep a reference to a mutable object from right
            if isinstance(right_value, dict):
                result[key] = deep_merge(right_value, {})
            else:
                result[key] = right_value

    return result

